use verus::prelude::*;

#[requires(a.len() == b.len())]
#[ensures(|c: Vec<u32>| c.len() == a.len())]
#[ensures(|c: Vec<u32>| forall(|i: nat| i < a.len() ==> c[i] == a[i] * b[i]))]
#[decreases(a.len())]
fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // Precondition: a.len() == b.len()
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x * y)
     .collect()
}

